type ProblemSimulationLoaderProps = {
  slug: string;
  title: string;
  category: string;
  difficulty: string;
  description: string;
};

export function ProblemSimulationLoader({
  slug,
  title,
  category,
  difficulty,
  description,
}: ProblemSimulationLoaderProps) {
  const Simulation = SIMULATION_COMPONENTS[slug as keyof typeof SIMULATION_COMPONENTS];
  if (Simulation) return <Simulation />;

  return (
    <div className="min-h-screen bg-transparent text-foreground p-8 flex flex-col items-center justify-center relative z-10">
      <div className="max-w-md w-full text-center space-y-4 rounded-2xl border border-white/10 bg-black p-8 shadow-2xl backdrop-blur-xl">
        <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[#FF1018]/10 text-[#FF3B41] border border-[#FF1018]/25">
          <Sparkles className="h-7 w-7 animate-pulse text-[#FF1018]" />
        </div>
        <span className="inline-block px-2.5 py-0.5 rounded-full text-xs font-semibold bg-[#FF1018]/10 text-[#FF3B41] border border-[#FF1018]/25">
          {category} · {difficulty}
        </span>
        <h1 className="text-2xl font-bold text-white">{title}</h1>
        <p className="text-sm text-zinc-400 leading-relaxed">{description}</p>
        <div className="pt-4 flex flex-col gap-2">
          <Link
            href="/animations/dsa/two-sum"
            className="w-full py-2.5 px-4 rounded-xl text-xs font-bold bg-[#FF1018] text-white hover:bg-[#E00C14] transition-colors shadow-lg shadow-[#FF1018]/20"
          >
            View Live Two Sum Interactive Simulation →
          </Link>
          <Link
            href="/animations/dsa"
            className="inline-flex items-center justify-center gap-1.5 py-2 px-4 rounded-xl text-xs font-semibold text-zinc-400 hover:text-white transition-colors"
          >
            <ArrowLeft className="h-3.5 w-3.5" />
            Back to All 646 Problems
          </Link>
        </div>
      </div>
    </div>
  );
}
